app.run(debug=True)

from flask import Flask, jsonify, request

app = Flask(__name__)

# --- слой хранения ---
TASKS = {
    1: {"id": 1, "title": "Купить молоко", "owner_id": 7, "done": False},
    2: {"id": 2, "title": "Написать отчёт", "owner_id": 12, "done": True},
}


# --- слой бизнес-логики: ничего не знает про Flask ---
def can_edit(task, user_id, role):
    return role == "admin" or task["owner_id"] == user_id


# --- слой маршрутизации: только свяжет запрос с логикой ---
@app.get("/api/tasks/<int:task_id>")
def get_task(task_id):
    task = TASKS.get(task_id)
    if task is None:
        return jsonify({"error": "задача не найдена"}), 404
    return jsonify(task)


app.run(debug=True)

